import os
import sys
import six
import time
import logging
import shutil
import subprocess
import psutil
from abc import ABCMeta, abstractmethod
from taf.internal.managedobject import ManagedObject
from taf.internal.managed.ssh.managed_ssh_connection import ManagedSshConnection
from taf.trafficgenerator.iperf.exceptions import CommandOutputTimeoutError
from taf.trafficgenerator.iperf.util import log_decorate, decorate_with_logging


@six.add_metaclass(ABCMeta)
class ExecutableResources(object):
    def __init__(self, pid, *args, **kwargs):
        self._pid = pid

    @property
    def pid(self):
        return self._pid

    @abstractmethod
    def release(self, **kwargs):
        """

        """


class LocalExecutableResources(ExecutableResources):
    def __init__(self, pid, file_object=None, logger=None):
        super(LocalExecutableResources, self).__init__(pid)
        self._file_object = file_object
        self._logger = logger or logging

    def release(self, recursive=True):
        self._logger.debug("release locally, recursive={}".format(recursive))
        process = psutil.Process(self._pid)

        if recursive:
            for child in process.children():
                child.terminate()
            process.terminate()

        if self._file_object:
            self._file_object.flush()
            self._file_object.close()
            self._file_object = None


class RemoteExecutableResources(ExecutableResources):
    def __init__(self, pid, host, logger=None):
        super(RemoteExecutableResources, self).__init__(pid)
        self._host = host
        self._logger = logger or logging

    def release(self):
        self._logger.debug("release remotely")
        kill_command = "kill -15 {pid}".format(pid=self.pid)
        self._host.stop_from_command(kill_command)


class RemoteADBExecutableResources(RemoteExecutableResources):
    def __init__(self, pid, host, serial_number=None, logger=None):
        self._logger = logger or logging
        super(RemoteADBExecutableResources, self).__init__(pid, host, self._logger)
        self._serial_option = "-s {} ".format(serial_number) if serial_number else ""

    def release(self):
        self._logger.debug("release adb remotely")
        kill_command = "adb {serial}shell kill -15 {pid}".format(serial=self._serial_option, pid=self.pid)
        self._host.stop_from_command(kill_command)


@six.add_metaclass(ABCMeta)
class IperfHost(ManagedObject):

    def __init__(self, *args, **kwargs):
        super(IperfHost, self).__init__()

    @property
    def hostname(self):
        raise NotImplementedError()

    def is_windows(self):
        raise NotImplementedError

    @property
    def builtin_iperf_commands_constructor(self):
        """a constructor can create new IperfCommands subclass instance,
        it can be the class object of IperfCommands subclass,
        or a function for creating the instance of IperfCommands subclass.
        the restriction is the constructor's arguments must be
        iperf_options, host, default_temporary_log"""
        return None

    @abstractmethod
    def start_daemon(self, executable, log_path, **kwargs):
        """
        start a daemon

        :param executable: executable object
        :type executable: object
        :param log_path: log path for iperf
        :type log_path: str
        :return int: pid
        """

    @abstractmethod
    def execute(self, command, **kwargs):
        """
        execute command through ssh

        :param command: command that user want to execute
        :type command: str
        :return str : output after command execute
        """

    @abstractmethod
    def fetch_file(self, src_path, dest_path):
        """
        fetch file from src_path to dest_path

        :param src_path: source file path
        :param dest_path: destination file path
        """

    @abstractmethod
    def remove_file(self, file_path):
        """
        remove file

        :param file_path: path of file to remove
        :type file_path: str
        :return bool: True/False
        """

    @staticmethod
    def _convert_str_to_bytes(string):
        if isinstance(string, six.string_types):
            string = string.encode('utf-8')
        return string


class IperfRemoteHost(IperfHost):
    """
    assume accessing remote host via SSH, so the CMDs will be unix-like
    """

    def __init__(self, host, username, password, port,
                 proxy_host=None, proxy_username=None, proxy_password=None, proxy_port=None,
                 logger=None):
        """
        :param host: host ip address
        :type host: str
        :param username: username for ssh login
        :type username: str
        :param password: password for ssh login
        :type password: str
        :param port: port for ssh login
        :type port: int
        :param proxy_host: proxy host ip address
        :type proxy: str
        :param proxy_username: username for proxy ssh login
        :type proxy_username: str
        :param proxy_password: password for proxy ssh login
        :type proxy_password: str
        :param proxy_port: port for proxy ssh login
        :type proxy_port: int
        :param logger: logger object
        """
        super(IperfRemoteHost, self).__init__()

        proxy_cnn = ManagedSshConnection(host=proxy_host,
                                         user=proxy_username,
                                         password=proxy_password,
                                         port=proxy_port) if proxy_host else None
        self._ssh = ManagedSshConnection(host, username, password, port, proxy=proxy_cnn)
        self.add_prerequisite(self._ssh)
        self._ssh_process = None
        self._logger = logger or logging

        log_decorator = log_decorate(self._logger)
        decorate_with_logging(self, log_decorator)

    @property
    def remote(self):
        return True

    @property
    def hostname(self):
        return self._ssh.host

    def is_windows(self):
        return False  # SSH will depend on cygwin httpd however the host is Windows OS

    def execute(self, command, timeout=None, get_pty=False):
        """
        execute command through ssh

        :param command: command that user want to execute
        :type command: str
        :return str : output after command execute
        """
        return self._execute(command=command, timeout=timeout) \
            if get_pty else self.run(command, timeout=timeout)

    def _execute(self, command, timeout):
        out = self._ssh.ssh_connection.execute(command=command, timeout=timeout)
        return self._convert_str_to_bytes(out)

    def run(self, command, timeout=None):
        self._send_command(command)
        out = self._read_output(timeout)
        return self._convert_str_to_bytes(out)

    def start_daemon(self, executable, log_path, options=None, command_template=None,
                     pid_extractor=None, **kwargs):

        options_str = str(options) if options else ""
        command = executable + options_str + ' > ' + log_path
        if command_template:
            command = command_template.format(command)

        out = self.run(command)
        if pid_extractor:
            return RemoteExecutableResources(pid=pid_extractor(out), host=self)
        return None

    def stop_from_command(self, command):
        self._send_command(command)

    def _send_command(self, command):
        """
        execute command through ssh

        :param command: command that user want to execute
        :type command: str
        """
        self._logger.debug("send command {}".format(command))
        self._ssh_process = self._ssh.ssh_connection.send_command(command=command)

    def _read_output(self, timeout):
        """

        :param timeout: timeout for read output
        :type timeout: int
        :return str : output after command execute
        """
        timeout = timeout or 60
        end_time = time.time() + timeout
        while time.time() < end_time:
            return self._ssh_process.read_output()
        raise CommandOutputTimeoutError("wait command output for {}s timeout".format(timeout))

    def fetch_file(self, src_path, dest_path):
        fp = self._ssh.ssh_connection.files
        log_msg = "fetching file to {}:\n"
        log_msg += "Remote path: {}"
        log_msg = log_msg.format(self._ssh.ssh_connection, src_path)
        self._logger.info(log_msg)

        self._logger.info("fetching file: {}".format(dest_path))
        fp.get(src_path, dest_path)

    def remove_file(self, file_path):
        fp = self._ssh.ssh_connection.files
        if fp.exists(file_path):
            self._ssh.ssh_connection.execute('rm -f {}'.format(file_path))

        if fp.exists(file_path):
            return False
        return True

    def mkdir(self, dir_path):
        self._ssh.ssh_connection.execute('mkdir -p {}'.format(dir_path))
        fp = self._ssh.ssh_connection.files
        return fp.exists(dir_path)

    def pid_exists(self, pid):
        out = self._ssh.ssh_connection.execute('ps -p {}'.format(pid))
        return str(pid) in str(out)

    def get_output(self, log_path):
        """
        Get traffic output

        :param log_path: iperf traffic statistic log path
        :return: str with raw output
        """
        log_msg = "reading file from {}:\n"
        log_msg += "Remote path: {}"
        log_msg = log_msg.format(self._ssh.ssh_connection, log_path)
        self._logger.info(log_msg)

        content = self.execute('cat {}'.format(log_path))
        self._logger.info("content is -->: {}".format(content))
        return content


class IperfLocalHost(IperfHost):
    def __init__(self, logger=None):
        super(IperfLocalHost, self).__init__()
        self._logger = logger or logging

        log_decorator = log_decorate(self._logger)
        decorate_with_logging(self, log_decorator)

    @property
    def remote(self):
        return False

    @property
    def hostname(self):
        return "localhost"

    def is_windows(self):
        return "win32" in sys.platform

    def start_daemon(self, executable, log_path, options=None, command_template=None, shell=False, **kwargs):

        if not shell:
            #  in Linux cannot get the real pid but pid + 1 when shell=True,
            #  pid + 1 cannot be insured when race condition
            #  so use shell=False instead
            log_file_obj = open(log_path, 'w+')
            options_arg_list = options.get_option_arg_list() if options else []
            proc = subprocess.Popen([executable, ] + options_arg_list,
                                    stdout=log_file_obj,
                                    stderr=log_file_obj,
                                    shell=False)
            return LocalExecutableResources(pid=proc.pid, file_object=log_file_obj)

        #  adb shell cannot run with shell=False on windows as tested
        options_str = str(options) if options else ""
        command = executable + options_str + ' > ' + log_path
        if command_template:
            command = command_template.format(command)

        proc = subprocess.Popen(command, stdout=subprocess.PIPE, shell=True)
        return LocalExecutableResources(proc.pid)

    @staticmethod
    def stop_from_command(self, command=None):
        proc = subprocess.Popen(command, stdout=subprocess.PIPE, shell=True)
        proc.terminate()

    def execute(self, command, **kwargs):
        """
        execute command through pipe

        :param command: command that user want to execute
        :type command: str
        :return pid : output after command execute
        """
        process = subprocess.Popen(command, stdout=subprocess.PIPE, shell=True)
        out = process.stdout.read()
        return self._convert_str_to_bytes(out)

    def fetch_file(self, src_path, dest_path):
        """
        fetch file from src_path to dest_path

        :param src_path: source file path
        :param dest_path: destination file path
        """
        shutil.copy2(src_path, dest_path)

    def remove_file(self, file_path):
        if os.path.isfile(file_path) and os.path.exists(file_path):
            try:
                os.remove(file_path)
            except Exception as e:
                self._logger.warning("failed to remove file for {}".format(e))
                return False

            if os.path.isfile(file_path) and os.path.exists(file_path):
                return False
        return True

    @staticmethod
    def mkdir(dir_path):
        if os.path.exists(dir_path) and os.path.isdir(dir_path):
            return True

        os.makedirs(dir_path)
        exist = os.path.exists(dir_path)
        is_dir = os.path.isdir(dir_path)
        return exist and is_dir

    @staticmethod
    def pid_exists(pid):
        return psutil.pid_exists(pid)

    def get_output(self, log_path):
        """
        Get traffic output

        :param log_path: iperf traffic statistic log path
        :return: str with raw output
        """
        log_msg = "reading file from localhost: {}".format(log_path)
        self._logger.info(log_msg)

        content = self.execute('cat {}'.format(log_path))
        self._logger.info("content is -->: {}".format(content))
        return content
